@GameTestHolder("treasuryloans") @PrefixGameTestTemplate(false)
public final class LoanGameTests {
    static class LoanActor extends GovernanceGameTests.Actor { int saves,failAfter=Integer.MAX_VALUE; Runnable afterSave; LoanActor(GameTestHelper h){super(h);} @Override public CompoundTag saveWithoutId(CompoundTag tag){if(++saves>failAfter)throw new IllegalStateException("Injected native player serialization failure");var result=super.saveWithoutId(tag);if(afterSave!=null)afterSave.run();return result;} }
    static class Fixture extends GovernanceGameTests.Fixture {
        final long base=System.currentTimeMillis()-10000;final Loans oldLoans;final LoanActor player;final GovernanceGameTests.Actor king;final Treasury.Currency currency;
        final Loans.Limits limits=new Loans.Limits(100000,2500,12,30,Loans.DAY,Loans.DAY,0);
        Fixture(GameTestHelper h){super(h);oldLoans=data.loans;data.loans=new Loans();player=new LoanActor(h);king=new GovernanceGameTests.Actor(h);currency=ChroniclesBridge.loaded()?CHRONICLES:EMERALD;profile(player);player.getInventory().setItem(0,new ItemStack(Items.EMERALD,64));player.getInventory().setItem(1,new ItemStack(Items.EMERALD,64));var named=new ItemStack(Items.DIAMOND_SWORD);named.set(DataComponents.CUSTOM_NAME,Component.literal("Preserved blade"));player.getInventory().setItem(5,named);data.treasury=new Treasury();data.treasury.addFunds(currency,100000,Treasury.Kind.DEPOSIT,king.getUUID(),"Public funds",1000);}
        UUID offered(){var next=data.loans.copy();var funds=data.treasury.copy();var id=next.request(player.getUUID(),"Aveline","Workshop",currency,1000,limits,base+1000);next.offer(funds,id,king.getUUID(),"Aetherion",1000,5,1,limits,false,base+2000);data.commitLoans(h.getLevel().getServer(),funds,next);return id;}
        void accept(UUID id){var next=data.loans.copy();next.accept(id,player.getUUID(),ChroniclesBridge.publicName(player),base+3000);LoanTransactions.commit(player,id,true,1000,base+3000,next,data.treasury.copy());}
        void pay(UUID id,boolean full,long time){time+=base;var next=data.loans.copy();var funds=data.treasury.copy();long amount=next.payment(id,player.getUUID(),full);next.repay(funds,id,player.getUUID(),ChroniclesBridge.publicName(player),amount,time);LoanTransactions.commit(player,id,false,amount,time,next,funds);}
        @Override public void close(){try{var f=TreasuryData.class.getDeclaredField("loanJournal");f.setAccessible(true);f.set(data,null);}catch(Exception e){throw new IllegalStateException(e);}data.loans=oldLoans;LoanService.logout(player.getUUID());LoanService.logout(king.getUUID());super.close();}
    }
    static void profile(GovernanceGameTests.Actor p){if(!ChroniclesBridge.loaded())return;try{var type=Class.forName("pt.cronicasrp.domain.CharacterProfile");Object value=type.getConstructor(boolean.class,String.class,int.class,String.class,String.class,String.class,String.class,long.class,long.class,String.class).newInstance(true,"Aveline",28,"origins:human","Native credit test","Aveline","Common",100000L,100000L,"");Object attachment=((java.util.function.Supplier<?>)Class.forName("pt.cronicasrp.ModAttachments").getField("PROFILE").get(null)).get();for(var m:p.getClass().getMethods())if(m.getName().equals("setData")&&m.getParameterCount()==2&&m.getParameterTypes()[0].isInstance(attachment)){m.invoke(p,attachment,value);break;}}catch(Exception e){throw new IllegalStateException(e);}}
    static void reject(GameTestHelper h,Runnable op){GovernanceGameTests.reject(h,op);}
    static void desk(Fixture f,GovernanceGameTests.Actor p){var pos=f.h.absolutePos(new BlockPos(4,1,4));f.h.getLevel().setBlockAndUpdate(pos,BlockRegistry.LOAN_DESK.get().defaultBlockState());p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+1.5);LoanService.open(p,pos);LoanService.requireSession(p);}
    static JsonObject payload(GovernanceGameTests.Actor p){var out=new JsonObject();out.addProperty("nonce",JsonParser.parseString(LoanService.snapshot(p,false,"")).getAsJsonObject().get("nonce").getAsString());return out;}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void principalAndInstallmentsUseDurableRealWalletReceipts(GameTestHelper h){try(var f=new Fixture(h)){long wallet=WalletBridge.balance(f.player,f.currency);var id=f.offered();f.accept(id);h.assertTrue(WalletBridge.balance(f.player,f.currency)==wallet+1000&&f.data.treasury.balance(f.currency)==99000,"Principal was created or charged twice");f.pay(id,false,4000);h.assertTrue(WalletBridge.balance(f.player,f.currency)==wallet+780&&f.data.treasury.balance(f.currency)==99220&&f.data.loans.get(id).remaining()==880,"Installment debit and public credit differ");f.pay(id,true,5000);h.assertTrue(WalletBridge.balance(f.player,f.currency)==wallet-100&&f.data.treasury.balance(f.currency)==100100&&f.data.loans.get(id).state()==Loans.State.SETTLED&&f.data.loanJournal()==null,"Full settlement did not conserve money");h.assertTrue(f.player.getInventory().getItem(5).getHoverName().getString().equals("Preserved blade"),"A wallet transfer overwrote unrelated items");var restored=f.reopen();h.assertTrue(restored.loans.get(id).state()==Loans.State.SETTLED&&restored.treasury.balance(f.currency)==100100,"Actual compressed data lost the settled debt");}System.out.println("TREASURY_LOAN_WALLET_PASSED");h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void fullEmeraldInventoryCannotConsumeAReservedOffer(GameTestHelper h){try(var f=new Fixture(h)){if(f.currency==EMERALD){var id=f.offered();for(int i=0;i<36;i++)f.player.getInventory().setItem(i,new ItemStack(Items.STONE,64));reject(h,()->f.accept(id));h.assertTrue(f.data.loans.get(id).state()==Loans.State.OFFERED&&f.data.treasury.balance(EMERALD)==99000&&f.data.loanJournal()==null,"A full inventory consumed a funded offer");}}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void receiptsCannotBeReplayedAfterACompletedPayment(GameTestHelper h){try(var f=new Fixture(h)){var id=f.offered();f.accept(id);reject(h,()->f.accept(id));long before=WalletBridge.balance(f.player,f.currency);f.pay(id,true,4000);reject(h,()->f.pay(id,true,4001));h.assertTrue(WalletBridge.balance(f.player,f.currency)==before-1100&&f.data.treasury.balance(f.currency)==100100,"Replayed settlement changed money");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void actualWalletSaveFailureRetainsAndRecoversTheSameReceipt(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){var id=f.offered();long before=WalletBridge.balance(f.player,f.currency);var file=h.getLevel().getServer().getWorldPath(LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");f.player.failAfter=f.player.saves+1;reject(h,()->f.accept(id));h.assertTrue(f.data.loanJournal()!=null&&f.data.loans.get(id).state()==Loans.State.OFFERED&&WalletBridge.balance(f.player,f.currency)==before+1000,"Interrupted principal lost its recovery intent");var interrupted=f.reopen();h.assertTrue(interrupted.loanJournal()!=null,"Intent never reached the actual world file");f.player.failAfter=Integer.MAX_VALUE;f.player.getPersistentData().remove(LoanTransactions.RECEIPT_KEY);f.player.load(NbtIo.readCompressed(file,NbtAccounter.create(104857600)));h.assertTrue(WalletBridge.balance(f.player,f.currency)==before,"Native restart source did not retain the durable starting wallet");LoanTransactions.recover(f.player);LoanTransactions.recover(f.player);h.assertTrue(f.data.loanJournal()==null&&f.data.loans.get(id).state()==Loans.State.ACTIVE&&WalletBridge.balance(f.player,f.currency)==before+1000,"Recovery duplicated or lost principal");}System.out.println("TREASURY_LOAN_RECOVERY_PASSED");h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void pendingWalletReceiptBlocksConcurrentPublicSpendingAndIncome(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){var id=f.offered();var file=h.getLevel().getServer().getWorldPath(LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");f.player.failAfter=f.player.saves+1;reject(h,()->f.accept(id));reject(h,()->CrownIncomeApi.credit(h.getLevel().getServer(),UUID.randomUUID(),f.currency.name(),10,f.king.getUUID(),"Public receipt during recovery"));reject(h,()->f.data.commitGovernance(h.getLevel().getServer(),f.data.treasury.copy(),f.data.governance.copy()));f.player.failAfter=Integer.MAX_VALUE;LoanTransactions.recover(f.player);h.assertTrue(f.data.treasury.balance(f.currency)==99000,"A concurrent transfer overwrote the principal receipt");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void bankWriteFailureBeforeWalletChangesLeavesEveryAmountUntouched(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){var id=f.offered();long before=WalletBridge.balance(f.player,f.currency);Files.delete(f.file);Files.createDirectory(f.file);reject(h,()->f.accept(id));h.assertTrue(f.data.loanJournal()==null&&f.data.loans.get(id).state()==Loans.State.OFFERED&&WalletBridge.balance(f.player,f.currency)==before,"Failed preparation changed the wallet or debt");Files.delete(f.file);}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void migrationPreservesOldPollsIncomeAndBalancesAndRejectsDowngradedLoans(GameTestHelper h){try(var f=new Fixture(h)){var tag=f.data.save(new CompoundTag(),h.getLevel().registryAccess());tag.remove("loans");tag.putInt("version",8);var old=TreasuryData.load(tag,h.getLevel().registryAccess());h.assertTrue(old.treasury.snapshot().equals(f.data.treasury.snapshot())&&old.loans.all().isEmpty()&&old.save(new CompoundTag(),h.getLevel().registryAccess()).getInt("version")==9,"Format eight migration changed public funds");var id=f.offered();var funded=f.data.save(new CompoundTag(),h.getLevel().registryAccess());funded.putInt("version",8);reject(h,()->TreasuryData.load(funded,h.getLevel().registryAccess()));h.assertTrue(f.reopen().loans.get(id).state()==Loans.State.OFFERED,"Offered escrow was lost");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void externalTaxAndVotesNeverEraseOutstandingLoanData(GameTestHelper h){try(var f=new Fixture(h)){var id=f.offered();CrownIncomeApi.credit(h.getLevel().getServer(),UUID.randomUUID(),f.currency.name(),25,f.king.getUUID(),"Income with reserved loan");f.data.commitGovernance(h.getLevel().getServer(),f.data.treasury.copy(),f.data.governance.copy());var saved=f.reopen();h.assertTrue(saved.loans.get(id).state()==Loans.State.OFFERED&&saved.treasury.balance(f.currency)==99025,"Tax or voting commit discarded the credit register");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void physicalDeskAndOneUseNonceProtectApplications(GameTestHelper h){try(var f=new Fixture(h)){reject(h,()->LoanService.requireSession(f.player));desk(f,f.player);var p=payload(f.player);p.addProperty("amount",100);p.addProperty("purpose","Tools");LoanService.request(f.player,"apply",p.toString());LoanService.request(f.player,"apply",p.toString());h.assertTrue(f.data.loans.all().size()==1,"Replayed nonce duplicated a request");f.player.setPos(f.player.getX()+20,f.player.getY(),f.player.getZ());reject(h,()->LoanService.requireSession(f.player));}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void ordinaryPlayersCannotApproveOrReadAnotherBorrowersRecords(GameTestHelper h){try(var f=new Fixture(h)){var pending=f.data.loans.copy();var id=pending.request(f.player.getUUID(),"Aveline","Workshop",f.currency,1000,f.limits,f.base+1000);f.data.commitLoans(h.getLevel().getServer(),f.data.treasury.copy(),pending);desk(f,f.king);var p=payload(f.king);p.addProperty("id",id.toString());p.addProperty("interest",0);p.addProperty("installments",1);p.addProperty("days",1);LoanService.request(f.king,"offer",p.toString());var snapshot=JsonParser.parseString(LoanService.snapshot(f.king,false,"")).getAsJsonObject();h.assertTrue(snapshot.getAsJsonArray("rows").isEmpty()&&snapshot.getAsJsonArray("events").isEmpty(),"Another player's financial records leaked");h.assertTrue(f.data.loans.get(id).state()==Loans.State.REQUESTED&&f.data.treasury.balance(f.currency)==100000,"Unauthorized caller approved an otherwise valid application");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void currentSwornPresidentAloneCanReviewAndLosesAuthorityAtExpiry(GameTestHelper h){try(var f=new Fixture(h);var council=CouncilFixture.loaded()?new CouncilFixture(h.getLevel().getServer()):null){long now=System.currentTimeMillis();if(council==null)f.data.treasury.setStandaloneManager(f.king.getUUID(),f.king.getUUID(),now);else{council.mandate(f.king.getUUID(),now-1000,now+60000,0);h.assertTrue(!LoanService.manager(f.king),"Unsworn President can approve credit");council.claim(now-1);}h.assertTrue(LoanService.manager(f.king),"Sworn President cannot review credit");if(council!=null){council.expire(now-1);h.assertTrue(!LoanService.manager(f.king),"Expired President retained credit powers");}}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void deskHasRealCraftingLootCreativeEntryAndWorldOwnedDebt(GameTestHelper h){try(var f=new Fixture(h)){var key=net.minecraft.resources.ResourceLocation.parse("kingdomtreasury:loan_desk");h.assertTrue(h.getLevel().getServer().getRecipeManager().byKey(key).isPresent(),"Credit counter recipe missing");var tab=net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("kingdomtreasury:crown_ledger"));tab.buildContents(new net.minecraft.world.item.CreativeModeTab.ItemDisplayParameters(net.minecraft.world.flag.FeatureFlags.DEFAULT_FLAGS,true,h.getLevel().registryAccess()));h.assertTrue(tab.getSearchTabDisplayItems().stream().anyMatch(s->s.is(BlockRegistry.LOAN_DESK_ITEM.get())),"Credit counter absent from creative search");var id=f.offered();desk(f,f.player);var pos=h.absolutePos(new BlockPos(4,1,4));h.getLevel().removeBlock(pos,false);h.assertTrue(f.data.loans.get(id).state()==Loans.State.OFFERED&&f.data.treasury.balance(f.currency)==99000,"Breaking a desk erased a loan or released its reserved money");reject(h,()->LoanService.requireSession(f.player));}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void interruptedRepaymentReplaysFromTheNativeStartingWalletOnlyOnce(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){var id=f.offered();f.accept(id);long before=WalletBridge.balance(f.player,f.currency);f.player.failAfter=f.player.saves+1;reject(h,()->f.pay(id,false,4000));h.assertTrue(f.data.loanJournal()!=null&&f.data.loans.get(id).paid()==0&&f.data.treasury.balance(f.currency)==99000,"Failed wallet save prematurely credited an installment");var file=h.getLevel().getServer().getWorldPath(LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");f.player.failAfter=Integer.MAX_VALUE;f.player.getPersistentData().remove(LoanTransactions.RECEIPT_KEY);f.player.load(NbtIo.readCompressed(file,NbtAccounter.create(104857600)));h.assertTrue(WalletBridge.balance(f.player,f.currency)==before,"Repayment starting wallet was not durable");LoanTransactions.recover(f.player);LoanTransactions.recover(f.player);h.assertTrue(WalletBridge.balance(f.player,f.currency)==before-220&&f.data.treasury.balance(f.currency)==99220&&f.data.loans.get(id).paid()==220,"Recovered installment was charged or credited twice");}h.succeed();}
    @GameTest(template="loan_empty",timeoutTicks=100)
    public static void completedWalletReceiptSurvivesFailureOfTheFinalTreasuryReplacement(GameTestHelper h)throws Exception{try(var f=new Fixture(h)){var id=f.offered();long before=WalletBridge.balance(f.player,f.currency);int failAt=f.player.saves+2;var backup=f.file.resolveSibling("loan-final-write-backup.dat");f.player.afterSave=()->{if(f.player.saves==failAt)try{Files.move(f.file,backup,StandardCopyOption.REPLACE_EXISTING);Files.createDirectory(f.file);}catch(Exception e){throw new IllegalStateException(e);}};reject(h,()->f.accept(id));h.assertTrue(f.data.loanJournal()!=null&&f.data.loans.get(id).state()==Loans.State.OFFERED&&WalletBridge.balance(f.player,f.currency)==before+1000,"Final treasury failure lost its funded wallet receipt");Files.delete(f.file);Files.move(backup,f.file);f.player.afterSave=null;var saved=h.getLevel().getServer().getWorldPath(LevelResource.PLAYER_DATA_DIR).resolve(f.player.getUUID()+".dat");f.player.getPersistentData().remove(LoanTransactions.RECEIPT_KEY);f.player.load(NbtIo.readCompressed(saved,NbtAccounter.create(104857600)));LoanTransactions.recover(f.player);LoanTransactions.recover(f.player);h.assertTrue(f.data.loanJournal()==null&&f.data.loans.get(id).state()==Loans.State.ACTIVE&&WalletBridge.balance(f.player,f.currency)==before+1000&&f.data.treasury.balance(f.currency)==99000,"Final write recovery repeated or lost a principal transfer");}h.succeed();}
}
